="color: #007700">);<br /><br /><br />if&nbsp;(&nbsp;</span><span style="color: #0000BB">sha1</span><span style="color: #007700">(</span><span style="color: #0000BB">$shana</span><span style="color: #007700">)&nbsp;===&nbsp;</span><span style="color: #0000BB">sha1</span><span style="color: #007700">(</span><span style="color: #0000BB">$passwd</span><span style="color: #007700">)&nbsp;&amp;&amp;&nbsp;</span><span style="color: #0000BB">$shana&nbsp;</span><span style="color: #007700">!=&nbsp;</span><span style="color: #0000BB">$passwd&nbsp;</span><span style="color: #007700">){<br />&nbsp;&nbsp;&nbsp;&nbsp;</span><span style="color: #0000BB">extract</span><span style="color: #007700">(</span><span style="color: #0000BB">$_GET</span><span style="color: #007700">[</span><span style="color: #DD0000">"flag"</span><span style="color: #007700">]);<br />&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;</span><span style="color: #DD0000">"Very&nbsp;good!&nbsp;you&nbsp;know&nbsp;my&nbsp;password.&nbsp;But&nbsp;what&nbsp;is&nbsp;flag?&lt;br&gt;"</span><span style="color: #007700">;<br />}&nbsp;else{<br />&nbsp;&nbsp;&nbsp;&nbsp;die(</span><span style="color: #DD0000">"fxck&nbsp;you!&nbsp;you&nbsp;don't&nbsp;know&nbsp;my&nbsp;password!&nbsp;And&nbsp;you&nbsp;don't&nbsp;know&nbsp;sha1!&nbsp;why&nbsp;you&nbsp;come&nbsp;here!"</span><span style="color: #007700">);<br />}<br /><br />if(</span><span style="color: #0000BB">preg_match</span><span style="color: #007700">(</span><span style="color: #DD0000">'/^[a-z0-9]*$/isD'</span><span style="color: #007700">,&nbsp;</span><span style="color: #0000BB">$code</span><span style="color: #007700">)&nbsp;||&nbsp;<br /></span><span style="color: #0000BB">preg_match</span><span style="color: #007700">(</span><span style="color: #DD0000">'/fil|cat|more|tail|tac|less|head|nl|tailf|ass|eval|sort|shell|ob|start|mail|\`|\{|\%|x|\&amp;|\$|\*|\||\&lt;|\"|\'|\=|\?|sou|show|cont|high|reverse|flip|rand|scan|chr|local|sess|id|source|arra|head|light|print|echo